#include <multiset>
#include <iostream>

int main() {
    std::multiset<int> coll = {5, 1, 5, 2, 5, 3};

    // Remove all instances of 5
    size_t num_removed = coll.erase(5); 

    std::cout << "Elements removed: " << num_removed << "\n";
    // coll now contains {1, 2, 3}

    num_removed = coll.erase(10); 
    std::cout << "Elements removed: " << num_removed << "\n";
}
